"use client";

/**
 * Title cards: full-frame statements that cut hard from one beat to the next,
 * each held long enough to read. On the last card one key word turns to the
 * primary colour, so the line ends on the word that matters.
 *
 * Written by Better Design.
 */
import { loadFont } from "@remotion/google-fonts/InterTight";
import { AbsoluteFill, useCurrentFrame } from "remotion";
import { easings, pickFont, progress, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER_TIGHT } = loadFont("normal", { weights: ["600", "700"], subsets: ["latin"] });

/** Frames each card takes to settle after its cut. */
const SETTLE = 12;
/** Frames after the last cut before the key word starts to change colour. */
const ACCENT_DELAY = 10;
const ACCENT_FRAMES = 14;

export interface TitleCardsProps {
  /** One statement per card, shown in order. Keep each to a short sentence. */
  cards?: string[];
  /** A word on the last card that lands in the primary colour. Matched without case or punctuation. */
  accent?: string;
  /** Frames each card holds before the hard cut to the next. The last card holds to the end. */
  holdFrames?: number;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter Tight. */
  font?: string;
}

const bare = (word: string): string => word.toLowerCase().replace(/[^\p{L}\p{N}]/gu, "");

/** Cut between full-frame statements and colour the last card's key word. */
export function TitleCards({
  cards = ["Most product videos run too long.", "Yours can say it in three lines.", "Say it once, and say it clearly."],
  accent = "clearly",
  holdFrames = 36,
  theme: themeOverride,
  font,
}: TitleCardsProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER_TIGHT);

  const hold = Math.max(1, holdFrames);
  const count = Math.max(1, cards.length);
  const index = Math.min(count - 1, Math.floor(frame / hold));
  const local = frame - index * hold;
  const isLast = index === count - 1;
  const text = cards[index] ?? "";

  // A hard cut, then the words settle a few pixels into place.
  const settle = easings.out(progress(local, 0, SETTLE));
  const accentT = isLast ? easings.out(progress(local, ACCENT_DELAY, ACCENT_FRAMES)) : 0;
  const words = text.split(/\s+/).filter(Boolean);
  const target = bare(accent);

  return (
    <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center", fontFamily: family }}>
      <div
        key={index}
        style={{
          maxWidth: 1480,
          padding: "0 120px",
          textAlign: "center",
          fontSize: 132,
          fontWeight: 700,
          lineHeight: 1.04,
          letterSpacing: "-0.025em",
          color: theme.foreground,
          textWrap: "balance",
          transform: `translateY(${(1 - settle) * 18}px) scale(${1.015 - settle * 0.015})`,
        }}
      >
        {words.map((word, i) => {
          const hit = isLast && target !== "" && bare(word) === target;
          return (
            <span key={`${word}-${i}`} style={{ position: "relative", display: "inline-block", marginRight: i < words.length - 1 ? "0.24em" : 0 }}>
              <span style={{ color: theme.foreground }}>{word}</span>
              {hit ? (
                <span
                  style={{
                    position: "absolute",
                    inset: 0,
                    color: theme.primary,
                    clipPath: `inset(-0.3em ${(1 - accentT) * 100}% -0.3em -0.1em)`,
                  }}
                >
                  {word}
                </span>
              ) : null}
            </span>
          );
        })}
      </div>
      <div style={{ position: "absolute", bottom: 88, display: "flex", gap: 12 }}>
        {cards.map((_, i) => (
          <div
            key={i}
            style={{
              width: i === index ? 40 : 10,
              height: 10,
              borderRadius: 5,
              background: i === index ? theme.primary : withAlpha(theme.foreground, i < index ? 0.35 : 0.12),
            }}
          />
        ))}
      </div>
    </AbsoluteFill>
  );
}
